import { InvalidServerUrlError } from '../errors.js';

// Builds the push-hub upgrade URL. The hub is mounted on the top-level mux, so the
// path is REPLACED wholesale with /ws/orchestrate/{id} — any base path or /api/v1
// prefix on serverUrl is intentionally dropped (see the base-path test). serverUrl's
// scheme is swapped to its ws equivalent (https->wss, http->ws) and machineId travels
// as a query param.
export function buildOrchestrateWsUrl(serverUrl: string, orchestrationId: string, machineId: string): string {
  let url: URL;
  try {
    url = new URL(serverUrl);
  } catch {
    throw new InvalidServerUrlError(serverUrl);
  }
  if (url.protocol === 'https:') url.protocol = 'wss:';
  else if (url.protocol === 'http:') url.protocol = 'ws:';
  else throw new InvalidServerUrlError(serverUrl);

  url.pathname = '/ws/orchestrate/' + encodeURIComponent(orchestrationId);
  url.search = '';
  url.searchParams.set('machineId', machineId);
  return url.toString();
}
