import { createHash } from 'node:crypto';
import type { PlaywrightListReport, PlaywrightJSONSuite, DiscoverUnit, DiscoverSpec } from './types.js';

// Flatten Playwright's file->describe->spec tree into (file, project) units. Each spec
// is duplicated per project in the source tree (one entry in spec.tests), so we fan
// out on spec.tests to stay correct even if a spec ever carries >1 project entry.
export function buildUnits(report: PlaywrightListReport): DiscoverUnit[] {
  const byKey = new Map<string, DiscoverUnit>();

  const visit = (suite: PlaywrightJSONSuite, titleChain: string[]): void => {
    const chain = [...titleChain, suite.title];
    for (const spec of suite.specs ?? []) {
      const tags = spec.tags ?? [];
      for (const test of spec.tests ?? []) {
        const key = JSON.stringify([spec.file, test.projectName]);
        let unit = byKey.get(key);
        if (!unit) {
          unit = { file: spec.file, project: test.projectName, tags: [], tests: [] };
          byKey.set(key, unit);
        }
        unit.tests.push({
          title: spec.title,
          titlePath: [test.projectName, ...chain, spec.title],
          tags,
          line: spec.line,
          column: spec.column,
        });
        for (const tag of tags) {
          if (!unit.tags.includes(tag)) unit.tags.push(tag);
        }
      }
    }
    for (const child of suite.suites ?? []) visit(child, chain);
  };

  for (const fileSuite of report.suites ?? []) visit(fileSuite, []);

  return [...byKey.values()].sort((a, b) => a.file.localeCompare(b.file) || a.project.localeCompare(b.project));
}

// Fingerprint over sorted (file|project) keys only - test-level nondeterminism
// (e.g. test.each) must not change it while the file SET is stable. The grep is
// folded in ONLY when present so two greps selecting different tests within the
// same file set mint distinct orchestrations (grep is now load-bearing at run
// time); a no-grep fingerprint is byte-identical to before.
export function computeSuiteFingerprint(units: DiscoverUnit[], grep?: string): string {
  const keys = units.map((u) => `${u.file}|${u.project}`).sort();
  const base = keys.join('\n');
  const input = grep ? `${base}\x00grep=${grep}` : base;
  return createHash('sha256').update(input).digest('hex');
}

// Re-group file-sorted units into one spec per file for the mint body. Only each
// test's titlePath survives — title/tags/line/column are dispatch-local and the
// backend estimator neither reads nor needs them.
export function buildDiscoverSpecs(units: DiscoverUnit[]): DiscoverSpec[] {
  const byFile = new Map<string, DiscoverSpec>();
  for (const unit of units) {
    let spec = byFile.get(unit.file);
    if (!spec) {
      spec = { file: unit.file, tests: [] };
      byFile.set(unit.file, spec);
    }
    for (const test of unit.tests) {
      spec.tests.push({ titlePath: test.titlePath });
    }
  }
  return [...byFile.values()];
}
