import { isAxiosError } from 'axios';

export type DispatchErrorKind = 'client' | 'server_error' | 'network';

// DispatchError normalizes every dispatcher call failure. `kind` drives retry:
// network/server_error are transient (retry, then fall back); client (4xx) is a
// real answer and never retried. httpStatus/serverCode let the caller act on
// specific outcomes (FINGERPRINT_MISMATCH is fatal, a 404 ack is benign).
export class DispatchError extends Error {
  readonly kind: DispatchErrorKind;
  readonly httpStatus?: number;
  readonly serverCode?: string;

  constructor(message: string, kind: DispatchErrorKind, httpStatus?: number, serverCode?: string) {
    super(message);
    this.name = 'DispatchError';
    this.kind = kind;
    this.httpStatus = httpStatus;
    this.serverCode = serverCode;
  }

  // 408 (request timeout) and 429 (rate limit) are 4xx but retryable — exactly
  // what backoff is designed to ride out.
  get transient(): boolean {
    if (this.kind !== 'client') return true;
    return this.httpStatus === 408 || this.httpStatus === 429;
  }
}

export function classifyDispatchError(error: unknown): DispatchError {
  if (error instanceof DispatchError) return error;
  if (isAxiosError(error)) {
    const status = error.response?.status;
    if (status === undefined) {
      return new DispatchError(error.message || 'network error', 'network');
    }
    const code = extractCode(error.response?.data);
    const message = extractMessage(error.response?.data) ?? error.message;
    const kind: DispatchErrorKind = status >= 500 ? 'server_error' : 'client';
    return new DispatchError(message, kind, status, code);
  }
  return new DispatchError(error instanceof Error ? error.message : String(error), 'network');
}

// The dispatcher error envelope is {"error":{"code","message"}} (data-handler
// shared.WriteError); tolerate a flat {code,message} too.
function extractCode(data: unknown): string | undefined {
  const d = data as Record<string, unknown> | undefined;
  const nested = d?.error as Record<string, unknown> | undefined;
  if (typeof nested?.code === 'string') return nested.code;
  if (typeof d?.code === 'string') return d.code;
  return undefined;
}

function extractMessage(data: unknown): string | undefined {
  const d = data as Record<string, unknown> | undefined;
  const nested = d?.error as Record<string, unknown> | undefined;
  if (typeof nested?.message === 'string') return nested.message;
  if (typeof d?.message === 'string') return d.message;
  return undefined;
}
