import { PlaywrightListRunner } from './playwright-list-runner.js';
import { buildUnits, buildDiscoverSpecs, computeSuiteFingerprint } from './unit-builder.js';
import { NoTestsDiscoveredError } from '../errors.js';
import type { DiscoverClient, MintDiscoverResponse } from './discover-client.js';

export interface DiscoverMintInput {
  grep?: string;
  project?: string[];
  machines: number;
  workers: number;
  fullyParallel: boolean;
}

export interface DiscoverMintResult extends MintDiscoverResponse {
  suiteFingerprint: string;
  totalTests: number;
}

// DiscoverMintCommand lists the filtered suite locally, fingerprints it, and mints
// an orchestration on the backend. It refuses to touch the network when discovery
// yields zero tests — an empty mint would 422 and waste a round trip.
export class DiscoverMintCommand {
  constructor(
    private readonly listRunner: PlaywrightListRunner = new PlaywrightListRunner(),
    private readonly client: DiscoverClient
  ) {}

  async execute(input: DiscoverMintInput): Promise<DiscoverMintResult> {
    const report = await this.listRunner.list({ grep: input.grep, projects: input.project });
    const units = buildUnits(report);
    const totalTests = units.reduce((n, u) => n + u.tests.length, 0);
    if (totalTests === 0) throw new NoTestsDiscoveredError(input.grep, input.project);

    const suiteFingerprint = computeSuiteFingerprint(units, input.grep);
    const specs = buildDiscoverSpecs(units);
    const response = await this.client.mint({
      suiteFingerprint,
      machines: input.machines,
      workers: input.workers,
      fullyParallel: input.fullyParallel,
      specs,
      ...(input.grep ? { grep: input.grep } : {}),
    });

    return { ...response, suiteFingerprint, totalTests };
  }
}
