export const DEFAULT_SERVER_URL = 'https://reporter.testdino.com';

import type { CompleteMetadata } from '../metadata/types.js';
import type { CoverageConfig, CoverageSummary, FileCoverage, CompactCoverageData } from '../code-coverage/index.js';

export type {
  CompleteMetadata as RunMetadata,
  GitMetadata,
  CIMetadata,
  PRMetadata,
  SystemMetadata,
  PlaywrightMetadata,
  ShardMetadata,
  MetadataCollectionResult,
  MetadataCollectionSummary,
  MetadataCollector,
} from '../metadata/types.js';

export type {
  CoverageConfig,
  CoverageThresholds,
  CoverageSummary,
  FileCoverage,
  CoverageMetric,
  CompactCoverageData,
  CompactFileCounts,
  CoverageFragment,
  IstanbulCoverageMap,
} from '../code-coverage/index.js';

export type { QuotaExhaustedError, QuotaExceededError, ServerError } from '../reporter/errors.js';
export type { SessionCreationQuotaResponse, NackMessage } from './errors.js';

export interface TestdinoConfig {
  token?: string;
  ciRunId?: string;
  // Manual-split group id — correlation key like ciRunId (CLI flag, testdino.config, reporter opts, or TESTDINO_SPLIT_ID env). The split position stays CLI-only.
  splitId?: string;
  // Orchestration group id — set only by `tdpw orchestrate run` (CLI flag, threaded to the reporter via temp-config). Mutually exclusive with splitId.
  orchestrationId?: string;
  serverUrl?: string;
  debug?: boolean;
  artifacts?: boolean;
  coverage?: CoverageConfig;
  tags?: string[];
}

export type TestEvent =
  | TestRunBeginEvent
  | TestBeginEvent
  | TestStepBeginEvent
  | TestStepEndEvent
  | TestEndEvent
  | TestRunEndEvent
  | TestRunErrorEvent
  | TestConsoleOutEvent
  | TestConsoleErrEvent
  | CoverageDataEvent
  | CompressedCoverageDataEvent
  | RunHeartbeatEvent;

export interface Annotation {
  type: string;
  description?: string;
}

export interface BaseEvent {
  type: string;
  timestamp: number;
  runId: string;
  sequence: number;
}

export interface TestRunBeginEvent extends BaseEvent {
  type: 'run:begin';
  projectId: string;
  metadata: CompleteMetadata;
  ciRunId?: string;
  shard?: {
    current: number;
    total: number;
  };
  splitId?: string;
  orchestrationId?: string;
  split?: {
    current: number;
    total: number;
  };
  coverageEnabled?: boolean;
  tags?: string[];
}

export interface TestBeginEvent extends BaseEvent {
  type: 'test:begin';
  testId: string;
  title: string;
  titlePath: Array<string>;
  location: {
    file: string;
    line: number;
    column: number;
  };
  tags: Array<string>;
  expectedStatus: 'passed' | 'failed' | 'timedOut' | 'skipped' | 'interrupted';
  timeout: number;
  retries: number;
  annotations: Array<Annotation>;
  retry: number;
  workerIndex: number;
  parallelIndex: number;
  repeatEachIndex?: number;
  parentSuite: {
    title: string;
    type: 'root' | 'project' | 'file' | 'describe';
    location?: {
      file: string;
      line: number;
      column: number;
    };
  };
  startTime: number;
}

export interface TestStepBeginEvent extends BaseEvent {
  type: 'step:begin';
  testId: string;
  stepId: string;
  title: string;
  titlePath: Array<string>;
  category: string;
  location?: {
    file: string;
    line: number;
    column: number;
  };
  parentStep?: {
    title: string;
    category: string;
    location?: {
      file: string;
      line: number;
      column: number;
    };
  };
  startTime: number;
  retry: number;
  workerIndex: number;
  parallelIndex: number;
  annotations: Array<Annotation>;
}

export interface TestStepEndEvent extends BaseEvent {
  type: 'step:end';
  testId: string;
  stepId: string;
  title?: string;
  titlePath?: string[];
  duration: number;
  error?: {
    message: string;
    stack?: string;
    snippet?: string;
    value?: string;
    location?: {
      file: string;
      line: number;
      column: number;
    };
  };
  status: 'passed' | 'failed';
  childSteps: {
    count: number;
    steps: Array<{
      title: string;
      status: 'passed' | 'failed';
    }>;
  };
  workerIndex: number;
  parallelIndex: number;
  // step attachments never carry path — would leak local FS.
  attachments: Array<{
    name: string;
    contentType: string;
  }>;
  annotations?: Array<Annotation>;
  retry: number;
}

export interface TestEndEvent extends BaseEvent {
  type: 'test:end';
  testId: string;
  status: 'passed' | 'failed' | 'skipped' | 'timedOut' | 'interrupted';
  outcome: 'expected' | 'unexpected' | 'flaky' | 'skipped';
  duration: number;
  retry: number;
  workerIndex: number;
  parallelIndex: number;
  annotations: Array<Annotation>;
  errors: Array<{
    message: string;
    stack?: string;
    snippet?: string;
    value?: string;
    location?: {
      file: string;
      line: number;
      column: number;
    };
  }>;
  steps: {
    total: number;
    passed: number;
    failed: number;
  };
  // Three mutually-exclusive states: uploaded (blobKey) / failed (unavailable) / in-memory (excluded upstream).
  // path never emitted — non-dereferenceable + PII.
  attachments: Array<{
    name: string;
    contentType: string;
    blobKey?: string;
    unavailable?: boolean;
  }>;
  stdout?: string[];
  stderr?: string[];
}

export interface TestRunEndEvent extends BaseEvent {
  type: 'run:end';
  status: 'passed' | 'failed' | 'timedout' | 'interrupted';
  duration: number;
  startTime: number;
  shard?: {
    current: number;
    total: number;
  };
  splitId?: string;
  orchestrationId?: string;
  split?: {
    current: number;
    total: number;
  };
  // Lets the server distinguish "instrumentation missing" from "delivery failed".
  coverageExpected?: boolean;
}

// No sequence — not part of event ordering.
export interface RunHeartbeatEvent {
  type: 'run:heartbeat';
  runId: string;
  timestamp: number;
}

export interface CoverageDataEvent extends BaseEvent {
  type: 'coverage:data';
  summary: CoverageSummary;
  files: FileCoverage[];
  // Present only for sharded runs.
  compactCounts?: CompactCoverageData;
  metadata: {
    instrumentationType: 'istanbul';
    fileCount: number;
    sharded: boolean;
  };
  shard?: {
    current: number;
    total: number;
  };
  splitId?: string;
  split?: {
    current: number;
    total: number;
  };
}

// Sent instead of CoverageDataEvent when the JSON payload exceeds 1MB.
// Ingestion decodes: JSON.parse(gunzipSync(Buffer.from(payload, 'base64')).toString('utf8')).
export interface CompressedCoverageDataEvent {
  type: 'coverage:data';
  runId: string;
  timestamp: number;
  sequence: number;
  compression: 'gzip';
  payload: string;
}

export interface TestRunErrorEvent extends BaseEvent {
  type: 'run:error';
  error: {
    message?: string;
    stack?: string;
    value?: string;
    snippet?: string;
    location?: {
      file: string;
      line: number;
      column: number;
    };
    // v1.49+
    cause?: {
      message?: string;
      stack?: string;
      value?: string;
      snippet?: string;
      location?: {
        file: string;
        line: number;
        column: number;
      };
    };
  };
}

export interface TestConsoleOutEvent extends BaseEvent {
  type: 'console:out';
  text: string; // Chunk, UTF-8, max 10KB.
  testId?: string;
  retry?: number;
  truncated?: boolean;
}

export interface TestConsoleErrEvent extends BaseEvent {
  type: 'console:err';
  text: string; // Chunk, UTF-8, max 10KB.
  testId?: string;
  retry?: number;
  truncated?: boolean;
}
