import { randomUUID } from 'crypto';
import { readFileSync, unlinkSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';
import { execa, type ExecaError } from 'execa';
import type { MergedConfig } from './types.js';
import { Logger } from './logger.js';

export interface PlaywrightSpawnOptions {
  args: string[];
  tempConfigPath: string;
  config: MergedConfig;
  cwd?: string;
}

export interface PlaywrightSpawnResult {
  exitCode: number;
  success: boolean;
  // resultsProduced = the reporter wrote totalTests>0 to the sentinel file. It is
  // the ack gate for orchestration: a batch that produced no results must never be
  // acked (the backend re-distributes it), or its tests are silently lost.
  resultsProduced: boolean;
  totalTests: number;
}

export class PlaywrightSpawner {
  private logger: Logger;

  constructor(logger?: Logger) {
    this.logger = logger ?? new Logger();
  }

  async spawn(options: PlaywrightSpawnOptions): Promise<PlaywrightSpawnResult> {
    const { args, tempConfigPath, config, cwd = process.cwd() } = options;

    // The reporter writes { totalTests } here from onEnd; the path is unique per
    // spawn so concurrent invocations never read each other's sentinel.
    const resultPath = join(tmpdir(), `testdino-result-${randomUUID()}.json`);

    try {
      // Build environment variables
      const env = {
        ...process.env,
        TESTDINO_CLI_CONFIG_PATH: tempConfigPath,
        TESTDINO_TOKEN: config.token,
        ...(config.serverUrl !== undefined && { TESTDINO_SERVER_URL: config.serverUrl }),
        ...(config.ciRunId !== undefined && { TESTDINO_CI_RUN_ID: config.ciRunId }),
        TESTDINO_DEBUG: config.debug ? 'true' : 'false',
        TESTDINO_RUN_RESULT_PATH: resultPath,
      };

      const playwrightArgs = ['playwright', 'test', '--reporter', '@testdino/playwright', ...args];

      // Spawn Playwright with execa
      const result = await execa('npx', playwrightArgs, {
        stdio: 'inherit', // Forward stdout/stderr in real-time
        cwd,
        env,
        reject: false, // Don't throw on non-zero exit codes
      });

      const exitCode = result.exitCode ?? 0;
      const totalTests = this.readTotalTests(resultPath);

      return {
        exitCode,
        success: exitCode === 0,
        resultsProduced: totalTests > 0,
        totalTests,
      };
    } catch (error) {
      return this.handleSpawnError(error);
    } finally {
      try {
        unlinkSync(resultPath);
      } catch {
        // The reporter may never have written it (spawn failure / globalSetup crash).
      }
    }
  }

  // A missing or corrupt sentinel means the reporter never reached onEnd (globalSetup
  // crash, immediate spawn failure) — treat that as zero tests produced.
  private readTotalTests(resultPath: string): number {
    try {
      const parsed = JSON.parse(readFileSync(resultPath, 'utf-8')) as { totalTests?: unknown };
      return typeof parsed.totalTests === 'number' ? parsed.totalTests : 0;
    } catch {
      return 0;
    }
  }

  private handleSpawnError(error: unknown): PlaywrightSpawnResult {
    const execaError = error as ExecaError;

    if (execaError.code === 'ENOENT') {
      this.logger.error('Failed to spawn Playwright');
      this.logger.newline();
      this.logger.info('Playwright is not installed or npx is not available.');
      this.logger.newline();
      this.logger.section('To install Playwright:');
      this.logger.code('npm install -D @playwright/test');
      this.logger.code('npx playwright install');
      return {
        exitCode: 1,
        success: false,
        resultsProduced: false,
        totalTests: 0,
      };
    }

    if (execaError.code === 'EACCES') {
      this.logger.error('Permission denied when trying to spawn Playwright');
      this.logger.newline();
      this.logger.info('Please check file permissions and try again.');
      return {
        exitCode: 1,
        success: false,
        resultsProduced: false,
        totalTests: 0,
      };
    }

    // Generic error
    this.logger.error('Failed to spawn Playwright');
    this.logger.newline();
    this.logger.info(`Error: ${execaError.message || String(error)}`);
    return {
      exitCode: 1,
      success: false,
      resultsProduced: false,
      totalTests: 0,
    };
  }
}
