export class TestDinoError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'TestDinoError';
    Error.captureStackTrace(this, this.constructor);
  }
}

export class TokenMissingError extends TestDinoError {
  constructor() {
    const message = `Token is required to run tests with TestDino

Provide token via:
  • CLI flag:    npx tdpw test --token <your-token>
  • Environment: export TESTDINO_TOKEN=<your-token>
  • Config file: Create testdino.config.ts with token

Get your token at: https://testdino.com/settings`;

    super(message);
    this.name = 'TokenMissingError';
  }
}

export class ConfigSyntaxError extends TestDinoError {
  constructor(configPath: string, originalError: Error) {
    const message = `Failed to load ${configPath}

${originalError.message}

Fix the syntax error and try again.`;

    super(message);
    this.name = 'ConfigSyntaxError';
  }
}

export class InvalidSplitFlagError extends TestDinoError {
  constructor(value: string) {
    const message = `Invalid --split value: ${value}

--split must be <current>/<total> with positive integers and current <= total.

Examples:
  • --split 1/5
  • --split 3/3`;

    super(message);
    this.name = 'InvalidSplitFlagError';
  }
}

export class InvalidMachineCountError extends TestDinoError {
  constructor(value?: string) {
    const seen = value === undefined ? '' : `: ${value}`;
    const message = `Invalid machine count${seen}

The number of machines is required and must be a positive integer.

Provide it via:
  • CLI flag:    npx tdpw orchestrate discover --machines <N>
  • Environment: export TESTDINO_MACHINES=<N>

Example:
  • --machines 4`;

    super(message);
    this.name = 'InvalidMachineCountError';
  }
}

export class SplitConfigMismatchError extends TestDinoError {
  constructor() {
    const message = `Split mode requires both a position (--split) and a group id (--split-id or TESTDINO_SPLIT_ID)

Provide both:
  • npx tdpw test --split 1/5 --split-id <group-id>
  • or set the id from the environment:  TESTDINO_SPLIT_ID=<group-id> npx tdpw test --split 1/5

The group id must be unique per pipeline execution so separate runs do not merge.`;

    super(message);
    this.name = 'SplitConfigMismatchError';
  }
}

export class OrchestrationSplitConflictError extends TestDinoError {
  constructor() {
    super(
      `Orchestration and manual-split modes are mutually exclusive — a run cannot carry both an orchestration id and a split id. Use one grouping mode per run.`
    );
    this.name = 'OrchestrationSplitConflictError';
  }
}

export class NoTestsDiscoveredError extends TestDinoError {
  constructor(grep?: string, project?: string[]) {
    const applied = [grep ? `--grep ${grep}` : '', project?.length ? `--project ${project.join(',')}` : '']
      .filter(Boolean)
      .join(' ');
    const message = `No tests matched discovery${applied ? ` for ${applied}` : ''}

Check your filters and that Playwright can collect tests in this directory.`;

    super(message);
    this.name = 'NoTestsDiscoveredError';
  }
}

export class DiscoveryFailedError extends TestDinoError {
  constructor(detail: string) {
    const message = `Failed to list tests via Playwright

${detail}

Ensure @playwright/test is installed and your Playwright config compiles:
  • npm install -D @playwright/test`;

    super(message);
    this.name = 'DiscoveryFailedError';
  }
}

export class InvalidServerUrlError extends TestDinoError {
  constructor(url: string) {
    const message = `Invalid server URL: ${url}

Server URL must be a valid HTTP or HTTPS URL.

Examples:
  • https://reporter.testdino.com
  • https://api-v0.testdino.com
  • https://global.testdino.com`;

    super(message);
    this.name = 'InvalidServerUrlError';
  }
}
