import { Command } from 'commander';
import { ConfigLoader } from '../config-loader.js';
import { ConfigDetector } from '../config-detector.js';
import { ConfigMerger } from '../config-merger.js';
import { Logger } from '../logger.js';
import { TestDinoError, TokenMissingError } from '../errors.js';
import { resolveDeviceId } from './device-id.js';
import { OrchestrateRunLoop } from './run-loop.js';

interface RunCliOptions {
  orchestrationId: string;
  deviceId?: string;
  token?: string;
  serverUrl?: string;
  debug?: boolean;
}

export function buildRunCommand(logger: Logger): Command {
  return (
    new Command('run')
      .description('Join an orchestration on this machine and run the test batches assigned to it')
      .requiredOption(
        '--orchestration-id <id>',
        'Orchestration id shared by every machine of one orchestrated run (from `orchestrate discover`)'
      )
      .option('--device-id <id>', 'Stable id for this machine (or TESTDINO_DEVICE_ID)')
      .option('--token <token>', 'TestDino pipeline token (or TESTDINO_TOKEN)')
      .option('--server-url <url>', 'TestDino server URL')
      .option('--debug', 'Enable debug logging')
      // Everything after the flags is forwarded verbatim to each `playwright test`
      // invocation (e.g. `-- --workers=2`). Scope the run with --grep/--project in
      // discover, not positional files, or the same files run on every batch.
      .allowUnknownOption()
      .allowExcessArguments()
      .action(async (options: RunCliOptions, command: Command) => {
        if (options.debug) logger.setDebug(true);

        try {
          const machineId = resolveDeviceId({ flag: options.deviceId });

          const testdinoConfig = await new ConfigLoader().load();
          const detection = await new ConfigDetector().detect();
          const merged = new ConfigMerger().merge({
            env: ConfigMerger.getEnvConfig(),
            playwrightConfig: detection.options,
            testdinoConfig: testdinoConfig.config,
            cliOptions: { token: options.token, serverUrl: options.serverUrl, debug: options.debug },
          });
          if (!merged.token) throw new TokenMissingError();

          const loop = new OrchestrateRunLoop({
            serverUrl: merged.serverUrl ?? '',
            token: merged.token,
            orchestrationId: options.orchestrationId,
            machineId,
            passthroughArgs: command.args ?? [],
            debug: options.debug,
            logger,
          });

          process.exitCode = await loop.run();
        } catch (error) {
          if (error instanceof TestDinoError) {
            logger.error(error.message);
          } else {
            logger.error(
              error instanceof Error ? error.message : String(error),
              error instanceof Error ? error : undefined
            );
          }
          process.exitCode = 1;
        }
      })
  );
}
