import { execa } from 'execa';
import type { PlaywrightListReport } from './types.js';
import { DiscoveryFailedError } from '../errors.js';

export interface ListRunnerOptions {
  grep?: string;
  projects?: string[];
  cwd?: string;
  env?: NodeJS.ProcessEnv;
}

// Pure arg construction — exported so it can be asserted without spawning Playwright.
export function buildListArgs(grep?: string, projects: string[] = []): string[] {
  return [
    'playwright',
    'test',
    '--list',
    '--reporter=json',
    ...(grep ? ['--grep', grep] : []),
    ...projects.flatMap((p) => ['--project', p]),
  ];
}

export class PlaywrightListRunner {
  async list(options: ListRunnerOptions = {}): Promise<PlaywrightListReport> {
    const { grep, projects = [], cwd = process.cwd(), env = process.env } = options;
    const args = buildListArgs(grep, projects);

    let result;
    try {
      // Capture stdout as data (the JSON report), not stream it to the terminal.
      result = await execa('npx', args, { cwd, env, reject: false, stdio: ['ignore', 'pipe', 'pipe'] });
    } catch (error) {
      const code = (error as { code?: string }).code;
      if (code === 'ENOENT') {
        throw new DiscoveryFailedError('Playwright is not installed or npx is not available.');
      }
      throw new DiscoveryFailedError(error instanceof Error ? error.message : String(error));
    }

    const stdout = result.stdout ?? '';
    if (result.exitCode !== 0 && !stdout.trim()) {
      throw new DiscoveryFailedError(result.stderr || `playwright exited with code ${result.exitCode}`);
    }

    try {
      return JSON.parse(stdout) as PlaywrightListReport;
    } catch (error) {
      throw new DiscoveryFailedError(
        `could not parse --list JSON: ${error instanceof Error ? error.message : String(error)}`
      );
    }
  }
}
