import { hostname } from 'os';

export interface DeviceIdSources {
  flag?: string;
  env?: NodeJS.ProcessEnv;
}

// resolveDeviceId picks a stable per-runner id. It MUST be called once and the
// result reused for the process's whole lifetime: a retried create-or-join with
// a freshly-minted id would become a non-creator and deadlock discovery.
// Precedence: explicit flag > TESTDINO_DEVICE_ID > CI matrix index > hostname+pid.
// GitHub Actions exposes NO native matrix index, so GH matrix legs fall through to
// hostname+pid (unique per process); set TESTDINO_DEVICE_ID to a matrix value there.
export function resolveDeviceId(sources: DeviceIdSources = {}): string {
  const flag = sources.flag?.trim();
  if (flag) return flag;

  const env = sources.env ?? process.env;
  const explicit = env.TESTDINO_DEVICE_ID?.trim();
  if (explicit) return explicit;

  const ciIndex = env.CI_NODE_INDEX?.trim() || env.CIRCLE_NODE_INDEX?.trim();
  if (ciIndex) return `ci-${ciIndex}`;

  return `${hostname()}-${process.pid}`;
}
