import type { IncomingMessage } from 'node:http';
import WebSocket from 'ws';
import type { RawData } from 'ws';
import { buildOrchestrateWsUrl } from './ws-url.js';

export type OrchestrateWsErrorKind = 'auth' | 'protocol' | 'exhausted';

export class OrchestrateWsError extends Error {
  readonly kind: OrchestrateWsErrorKind;

  constructor(message: string, kind: OrchestrateWsErrorKind) {
    super(message);
    this.name = 'OrchestrateWsError';
    this.kind = kind;
  }
}

// How connect() settled: 'ended' = the hub sent an end frame (session complete);
// 'closed' = the caller invoked close() (cancellation). Distinct so a caller can
// tell a finished run from an aborted one.
export type OrchestrateWsOutcome = 'ended' | 'closed';

export interface OrchestrateWsClientOptions {
  serverUrl: string;
  token: string;
  orchestrationId: string;
  machineId: string;
  // grep is the discover --grep pattern echoed by the hub (constant per session);
  // the caller re-applies it so a batch runs only the discovered tests, not whole files.
  onAssign: (specs: string[], grep?: string) => void;
  // Fires on every successful (re)connection. The caller re-issues any ack that
  // ack() dropped while the socket was down here — reconnection is otherwise
  // invisible, so this is the only retry trigger for the at-least-once ack path.
  onOpen?: () => void;
  onEnd?: () => void;
  onError?: (message: string) => void;
  onDebug?: (message: string) => void;
  maxReconnectAttempts?: number;
  baseReconnectDelayMs?: number;
  maxReconnectDelayMs?: number;
  handshakeTimeoutMs?: number;
  // No incoming ping/message within this window ⇒ the socket is half-open (server
  // died without a FIN) ⇒ terminate and reconnect. Coupled to the hub's keepalive:
  // it pings every pingPeriod (~54s = pongWait 60s × 9/10). Default 70s leaves slack
  // above that cadence; if the hub's pongWait/pingPeriod change, raise this to match.
  livenessTimeoutMs?: number;
}

// OrchestrateWsClient is the transport half of a machine's orchestration session:
// it holds one WebSocket to the push hub, reconnects transient drops with jittered
// backoff, detects half-open sockets via a ping/message liveness watchdog, and
// surfaces assign/end/error frames through callbacks. It deliberately carries NO
// run bookkeeping — the caller decides what to do with assigned specs and when to
// ack. Reconnects resume reading only; assigns are never replayed here.
export class OrchestrateWsClient {
  private readonly onAssign: (specs: string[], grep?: string) => void;
  private readonly onOpen: () => void;
  private readonly onEnd: () => void;
  private readonly onError: (message: string) => void;
  private readonly onDebug: (message: string) => void;
  private readonly maxReconnectAttempts: number;
  private readonly baseReconnectDelayMs: number;
  private readonly maxReconnectDelayMs: number;
  private readonly handshakeTimeoutMs: number;
  private readonly livenessTimeoutMs: number;

  private ws: WebSocket | null = null;
  private connectPromise: Promise<OrchestrateWsOutcome> | null = null;
  private resolveConnect: ((outcome: OrchestrateWsOutcome) => void) | null = null;
  private rejectConnect: ((err: OrchestrateWsError) => void) | null = null;
  private settled = false;
  private closedByCaller = false;
  private attempt = 0;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private livenessTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(private readonly options: OrchestrateWsClientOptions) {
    this.onAssign = options.onAssign;
    this.onOpen = options.onOpen ?? (() => {});
    this.onEnd = options.onEnd ?? (() => {});
    this.onError = options.onError ?? (() => {});
    this.onDebug = options.onDebug ?? (() => {});
    this.maxReconnectAttempts = options.maxReconnectAttempts ?? 10;
    this.baseReconnectDelayMs = options.baseReconnectDelayMs ?? 1000;
    this.maxReconnectDelayMs = options.maxReconnectDelayMs ?? 30_000;
    this.handshakeTimeoutMs = options.handshakeTimeoutMs ?? 15_000;
    this.livenessTimeoutMs = options.livenessTimeoutMs ?? 70_000;
  }

  // Runs the whole session. The returned promise resolves ONCE, when the hub sends
  // an end frame ('ended') or the caller calls close() ('closed'), and rejects on a
  // fatal error (auth/protocol/exhausted). Do NOT await it before acking — acks are
  // issued from the onAssign / onOpen callbacks while the session is live; awaiting
  // connect() first would block until the session is already over.
  connect(): Promise<OrchestrateWsOutcome> {
    if (this.connectPromise) return this.connectPromise;
    this.connectPromise = new Promise<OrchestrateWsOutcome>((resolve, reject) => {
      this.resolveConnect = resolve;
      this.rejectConnect = reject;
    });
    this.openSocket();
    return this.connectPromise;
  }

  // Sends an ack frame only on an open socket. Returns false (and debug-logs) when
  // the socket is down or the send throws (a CLOSING race): the caller must retry
  // — from onOpen once reconnected — because a dropped ack means the server never
  // learns those runIds landed. The 256KiB frame cap is generous for runIds.
  ack(runIds: string[]): boolean {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      this.onDebug(`ack skipped: socket not open (${runIds.length} runIds)`);
      return false;
    }
    try {
      this.ws.send(JSON.stringify({ action: 'ack', runIds }));
      return true;
    } catch (err) {
      this.onDebug(`ack send failed: ${err instanceof Error ? err.message : String(err)}`);
      return false;
    }
  }

  close(): void {
    this.closedByCaller = true;
    this.clearReconnectTimer();
    this.clearLivenessTimer();
    if (this.ws) this.ws.close(1000);
    this.resolveWith('closed');
  }

  private openSocket(): void {
    if (this.settled || this.closedByCaller) return;
    const url = buildOrchestrateWsUrl(this.options.serverUrl, this.options.orchestrationId, this.options.machineId);
    // handshakeTimeout arms ws's own upgrade timer: a server that accepts TCP but
    // stalls the upgrade emits 'error' (ETIMEDOUT) → scheduleReconnect, instead of
    // hanging connect() forever.
    const socket = new WebSocket(url, {
      headers: { Authorization: `Bearer ${this.options.token}` },
      handshakeTimeout: this.handshakeTimeoutMs,
    });
    this.ws = socket;

    socket.on('open', () => {
      if (socket !== this.ws) return;
      this.attempt = 0;
      this.resetLivenessTimer();
      this.onDebug('orchestrate socket open');
      // onOpen does real work (re-issuing dropped acks); a throw here must not
      // escape as an uncaught emitter exception.
      this.safeInvoke(() => this.onOpen(), 'onOpen');
    });
    socket.on('message', (data: RawData) => {
      if (socket !== this.ws) return;
      this.resetLivenessTimer();
      this.handleMessage(data);
    });
    // The server drives keepalive (it pings; ws auto-pongs). A received ping is
    // proof of life — reset the watchdog on it as well as on data frames.
    socket.on('ping', () => {
      if (socket !== this.ws) return;
      this.resetLivenessTimer();
    });
    socket.on('error', (err: Error) => {
      if (socket !== this.ws) return;
      this.onDebug(`orchestrate socket error: ${err.message}`);
      this.scheduleReconnect();
    });
    socket.on('close', () => {
      if (socket !== this.ws) return;
      // The end FRAME — not the close code — is the authoritative completion signal:
      // an end frame has already settled (settled guard makes this a no-op). A bare
      // close WITHOUT a prior end (any code, incl. 1000 on a server redeploy) means
      // the session is not finished, so reconnect to continue on another replica.
      this.scheduleReconnect();
    });
    socket.on('unexpected-response', (_req: unknown, res: IncomingMessage) => {
      if (socket !== this.ws) return;
      const status = res.statusCode ?? 0;
      // A 4xx is a refusal (fatal), EXCEPT the transient throttle/timeout codes,
      // which back off and retry like a 5xx.
      const retryable = status === 408 || status === 425 || status === 429;
      if (status >= 400 && status < 500 && !retryable) {
        this.rejectWith(`orchestrate handshake rejected with ${status}`, 'auth');
      } else {
        this.onDebug(`orchestrate handshake responded ${status} — reconnecting`);
        this.scheduleReconnect();
      }
      socket.terminate();
    });
  }

  private handleMessage(data: RawData): void {
    // Once connect() has settled the terminal callback already fired; drop any
    // later frame (error-then-end, a second end) so the caller sees no duplicate.
    if (this.settled) return;
    let msg: unknown;
    try {
      msg = JSON.parse(data.toString());
    } catch {
      this.onDebug('ignoring non-JSON frame');
      return;
    }
    if (!msg || typeof msg !== 'object') {
      this.onDebug('ignoring malformed frame');
      return;
    }
    const frame = msg as { event?: unknown; specs?: unknown; grep?: unknown; data?: unknown };
    switch (frame.event) {
      case 'assign': {
        if (!Array.isArray(frame.specs) || !frame.specs.every((s) => typeof s === 'string')) {
          this.onDebug('ignoring assign frame with malformed specs');
          return;
        }
        const grep = typeof frame.grep === 'string' ? frame.grep : undefined;
        this.safeInvoke(() => this.onAssign(frame.specs as string[], grep), 'onAssign');
        return;
      }
      case 'end': {
        // Settle FIRST so a throwing onEnd can never leave connect() unsettled with a
        // live timer; the callback is then invoked defensively.
        this.resolveWith('ended');
        this.safeInvoke(() => this.onEnd(), 'onEnd');
        this.ws?.close(1000);
        return;
      }
      case 'error': {
        const payload = frame.data as { message?: unknown } | undefined;
        const message = typeof payload?.message === 'string' ? payload.message : 'orchestration error';
        this.rejectWith(message, 'protocol');
        this.safeInvoke(() => this.onError(message), 'onError');
        return;
      }
      default:
        this.onDebug(`ignoring frame with unknown event: ${String(frame.event)}`);
    }
  }

  private scheduleReconnect(): void {
    this.clearLivenessTimer();
    if (this.settled || this.closedByCaller) return;
    // A pending timer is the single source of truth for "reconnect already queued",
    // deduping the error+close pair that a single drop fires.
    if (this.reconnectTimer) return;
    this.attempt++;
    if (this.attempt > this.maxReconnectAttempts) {
      this.rejectWith(`orchestrate socket unreachable after ${this.maxReconnectAttempts} attempts`, 'exhausted');
      return;
    }
    const delay = this.backoffDelay(this.attempt);
    this.onDebug(`orchestrate reconnect attempt ${this.attempt} in ${Math.round(delay)}ms`);
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      this.openSocket();
    }, delay);
  }

  private backoffDelay(attempt: number): number {
    const capped = Math.min(this.baseReconnectDelayMs * Math.pow(2, attempt - 1), this.maxReconnectDelayMs);
    return capped * (0.8 + Math.random() * 0.4);
  }

  // Terminates a socket that has gone quiet past livenessTimeoutMs (half-open, no
  // FIN). terminate() fires 'close' → scheduleReconnect.
  private resetLivenessTimer(): void {
    this.clearLivenessTimer();
    if (this.settled || this.closedByCaller) return;
    const socket = this.ws;
    this.livenessTimer = setTimeout(() => {
      this.livenessTimer = null;
      if (socket !== this.ws) return;
      this.onDebug(`orchestrate socket silent for ${this.livenessTimeoutMs}ms — terminating to reconnect`);
      socket?.terminate();
    }, this.livenessTimeoutMs);
  }

  private clearLivenessTimer(): void {
    if (this.livenessTimer) {
      clearTimeout(this.livenessTimer);
      this.livenessTimer = null;
    }
  }

  private clearReconnectTimer(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }

  // Invokes a caller callback without letting its throw escape (which would abort a
  // ws EventEmitter handler and can crash the process); the failure is debug-logged.
  private safeInvoke(fn: () => void, label: string): void {
    try {
      fn();
    } catch (err) {
      this.onDebug(`${label} callback threw: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  private resolveWith(outcome: OrchestrateWsOutcome): void {
    if (this.settled) return;
    this.settled = true;
    this.clearLivenessTimer();
    this.clearReconnectTimer();
    this.resolveConnect?.(outcome);
  }

  private rejectWith(message: string, kind: OrchestrateWsErrorKind): void {
    if (this.settled) return;
    this.settled = true;
    this.clearLivenessTimer();
    this.clearReconnectTimer();
    if (this.ws) this.ws.close(1000);
    this.rejectConnect?.(new OrchestrateWsError(message, kind));
  }
}
