import { writeFileSync } from 'fs';
import { Command } from 'commander';
import { ConfigLoader } from '../config-loader.js';
import { ConfigDetector } from '../config-detector.js';
import { ConfigMerger } from '../config-merger.js';
import { Logger } from '../logger.js';
import { TestDinoError, TokenMissingError } from '../errors.js';
import { DispatchError } from './dispatch-errors.js';
import { resolveMachineCount } from './machine-count.js';
import { HttpDiscoverClient, describeMintError } from './discover-client.js';
import { DiscoverMintCommand } from './discover-mint.js';

interface DiscoverCliOptions {
  grep?: string;
  project?: string[];
  out?: string;
  debug?: boolean;
  machines?: string;
  token?: string;
  serverUrl?: string;
}

export function buildDiscoverCommand(logger: Logger): Command {
  return new Command('discover')
    .description('Discover the filtered test set and mint an orchestration (no tests are executed)')
    .option('--grep <pattern>', 'Only include tests matching the pattern (Playwright --grep)')
    .option('--project <name...>', 'Restrict discovery to one or more Playwright projects')
    .option(
      '--machines <N>',
      'Number of machines to distribute across (or TESTDINO_MACHINES). Workers (W) is read from the Playwright config file and may differ from the runtime-effective workers if the run passes --workers / PLAYWRIGHT_WORKERS.'
    )
    .option('--token <token>', 'TestDino pipeline token (or TESTDINO_TOKEN)')
    .option('--server-url <url>', 'TestDino server URL')
    .option('--out <file>', 'Write the mint response (including orchestrationId) as JSON')
    .option('--debug', 'Enable debug logging')
    .action(async (options: DiscoverCliOptions) => {
      if (options.debug) logger.setDebug(true);

      try {
        const machines = resolveMachineCount({ flag: options.machines, env: process.env.TESTDINO_MACHINES });

        const testdinoConfig = await new ConfigLoader().load();
        const detection = await new ConfigDetector().detect();
        const merged = new ConfigMerger().merge({
          env: ConfigMerger.getEnvConfig(),
          playwrightConfig: detection.options,
          testdinoConfig: testdinoConfig.config,
          cliOptions: { token: options.token, serverUrl: options.serverUrl, debug: options.debug },
        });
        if (!merged.token) throw new TokenMissingError();

        const workers = detection.workers ?? 1;
        if (detection.workers === undefined) {
          logger.warn(
            'workers not set to a positive integer in the Playwright config (a percentage cannot be resolved at discover time) — defaulting to 1; set an integer for accurate distribution'
          );
        }
        const fullyParallel = detection.fullyParallel ?? false;

        const client = new HttpDiscoverClient({
          token: merged.token,
          serverUrl: merged.serverUrl ?? '',
          onDebug: (m) => logger.debug(m),
        });

        const result = await new DiscoverMintCommand(undefined, client).execute({
          grep: options.grep,
          project: options.project,
          machines,
          workers,
          fullyParallel,
        });

        logger.success(
          result.created
            ? `Minted orchestration ${result.orchestrationId}`
            : `Orchestration ${result.orchestrationId} already minted for this suite (idempotent retry)`
        );
        logger.listItem(`machines: ${result.machines}`);
        logger.listItem(`workers: ${result.workers}`);
        logger.listItem(`fullyParallel: ${result.fullyParallel}`);
        logger.listItem(`specCount: ${result.specCount}`);

        if (options.out) {
          writeFileSync(options.out, `${JSON.stringify(result, null, 2)}\n`, 'utf-8');
          logger.listItem(`mint response written to ${options.out}`);
        }
      } catch (error) {
        if (error instanceof DispatchError) {
          logger.error(`Discovery mint failed: ${describeMintError(error)}`);
        } else if (error instanceof TestDinoError) {
          logger.error(error.message);
        } else {
          logger.error(
            error instanceof Error ? error.message : String(error),
            error instanceof Error ? error : undefined
          );
        }
        process.exitCode = 1;
      }
    });
}
