import { randomUUID } from 'crypto';
import { TestCommand } from '../commands/test.js';
import { Logger } from '../logger.js';
import { OrchestrateWsClient, OrchestrateWsError } from './ws-client.js';
import type { OrchestrateWsClientOptions, OrchestrateWsOutcome } from './ws-client.js';

export interface OrchestrateRunLoopOptions {
  serverUrl: string;
  token: string;
  orchestrationId: string;
  machineId: string;
  passthroughArgs: string[];
  debug?: boolean;
  logger: Logger;
  testCommand?: TestCommand;
  clientFactory?: (options: OrchestrateWsClientOptions) => OrchestrateWsClient;
}

// OrchestrateRunLoop is one machine's orchestration session: it holds a WS client,
// runs each assigned spec batch as a single `playwright test` invocation with the
// reporter attached, and acks ONLY batches that produced results. A no-results batch
// is never acked — the loop reconnects so the backend re-distributes it — which is
// the whole point: an unconditional ack would silently lose those tests.
export class OrchestrateRunLoop {
  private readonly serverUrl: string;
  private readonly token: string;
  private readonly orchestrationId: string;
  private readonly machineId: string;
  private readonly passthroughArgs: string[];
  private readonly debug: boolean;
  private readonly logger: Logger;
  private readonly testCommand: TestCommand;
  private readonly clientFactory: (options: OrchestrateWsClientOptions) => OrchestrateWsClient;

  private client: OrchestrateWsClient | null = null;
  // The discover --grep echoed by the hub, re-applied to each batch so a runner
  // executes only the discovered tests, not every test in the assigned files.
  private assignGrep?: string;
  private busy = false;
  // Single-slot: one queued assign absorbs the benign race of a second assign
  // arriving while a batch runs; a third (already-queued) is a protocol violation.
  private queued: string[] | null = null;
  // runIds whose ack was dropped by a socket-down send; re-issued from onOpen.
  private pendingAcks: string[] = [];
  private reconnectRequested = false;
  private sigintRequested = false;
  private fatalOverlap = false;

  constructor(options: OrchestrateRunLoopOptions) {
    this.serverUrl = options.serverUrl;
    this.token = options.token;
    this.orchestrationId = options.orchestrationId;
    this.machineId = options.machineId;
    this.passthroughArgs = options.passthroughArgs;
    this.debug = options.debug ?? false;
    this.logger = options.logger;
    this.testCommand =
      options.testCommand ??
      new TestCommand(undefined, undefined, undefined, undefined, undefined, undefined, this.logger);
    this.clientFactory = options.clientFactory ?? ((opts) => new OrchestrateWsClient(opts));
  }

  async run(): Promise<number> {
    const onSigint = (): void => {
      this.sigintRequested = true;
      this.client?.close();
    };
    process.on('SIGINT', onSigint);

    try {
      for (;;) {
        this.client = this.buildClient();

        let outcome: OrchestrateWsOutcome;
        try {
          outcome = await this.client.connect();
        } catch (error) {
          if (error instanceof OrchestrateWsError) {
            this.logger.error(`Orchestration session failed: ${error.message}`);
            return 1;
          }
          throw error;
        }

        // A protocol overlap aborts non-zero regardless of how the socket settled.
        if (this.fatalOverlap) return 1;

        if (outcome === 'ended') return 0;

        // 'closed': SIGINT wins over everything — a Ctrl-C that races a no-results
        // reconnect must stop the run, not be absorbed into another reconnect.
        if (this.sigintRequested) return 130;
        // Otherwise a no-results batch requested a reconnect; a bare graceful close
        // with nothing pending is a clean stop.
        if (this.reconnectRequested) {
          this.reconnectRequested = false;
          continue;
        }
        return 0;
      }
    } finally {
      process.removeListener('SIGINT', onSigint);
    }
  }

  private buildClient(): OrchestrateWsClient {
    const options: OrchestrateWsClientOptions = {
      serverUrl: this.serverUrl,
      token: this.token,
      orchestrationId: this.orchestrationId,
      machineId: this.machineId,
      onAssign: (specs, grep) => this.onAssign(specs, grep),
      onOpen: () => this.onOpen(),
      onDebug: this.debug ? (m) => this.logger.debug(m) : undefined,
    };
    return this.clientFactory(options);
  }

  // onAssign is a SYNC ws callback — it must NOT await the run, or it blocks the
  // socket's read pump. It schedules processAssign fire-and-forget behind a busy guard.
  private onAssign(specs: string[], grep?: string): void {
    // grep is constant per orchestration; record the latest so a queued batch
    // (and a post-reconnect one) re-applies the same filter.
    this.assignGrep = grep;
    if (this.busy) {
      if (this.queued !== null) {
        this.fatalOverlap = true;
        this.logger.error('Orchestration protocol violation: a second batch was assigned while one was already queued');
        this.client?.close();
        return;
      }
      this.queued = specs;
      return;
    }
    this.busy = true;
    void this.processAssign(specs);
  }

  private async processAssign(specs: string[]): Promise<void> {
    try {
      // An empty batch has no file filter — invoking `playwright test` with only the
      // passthrough args would run the ENTIRE suite and get acked under one runId (a
      // silent over-run). Treat it as no-results: never ack, reconnect so the backend
      // re-distributes it.
      if (specs.length === 0) {
        this.logger.debug('Received an empty batch (no specs); requeuing via reconnect');
        this.reconnectRequested = true;
        this.client?.close();
        return;
      }

      // One assign = one runId = one reporter invocation. The SAME runId goes to the
      // reporter (via options.runId) and to ack(), so the dispatcher manifest and the
      // ingestion run:end key match.
      const runId = randomUUID();
      const result = await this.testCommand.execute(
        {
          token: this.token,
          serverUrl: this.serverUrl,
          debug: this.debug,
          orchestrationId: this.orchestrationId,
          runId,
          deviceId: this.machineId,
        },
        [...this.passthroughArgs, ...this.grepArgs(), ...specs]
      );

      if (result.resultsProduced) {
        const acked = this.client?.ack([runId]) ?? false;
        if (!acked) this.pendingAcks.push(runId);
      } else {
        // No results → never ack. Reconnect so the backend's crash-requeue (which
        // fires on any disconnect with an unacked inflight batch) re-distributes it.
        this.reconnectRequested = true;
        this.client?.close();
      }
    } catch (error) {
      // TestCommand.execute catches its own spawn failures, so a throw here is
      // unexpected. Treat it as no-results — never ack — and reconnect to requeue.
      this.reconnectRequested = true;
      this.logger.error(
        `Orchestration batch execution error: ${error instanceof Error ? error.message : String(error)}`
      );
      this.client?.close();
    } finally {
      this.busy = false;
      // Drain the queued batch ONLY on a clean continuation. After any close() — a
      // no-results/empty/error reconnect, SIGINT, or an overlap abort — the backend
      // re-distributes the queued batch on the disconnect; running it locally too would
      // double-run (and its ack/close would land on the replacement client).
      if (this.queued !== null) {
        if (this.reconnectRequested || this.sigintRequested || this.fatalOverlap) {
          this.queued = null;
        } else {
          const next = this.queued;
          this.queued = null;
          this.busy = true;
          void this.processAssign(next);
        }
      }
    }
  }

  // The propagated discover --grep, as playwright args — unless the caller already
  // passed a --grep in passthrough (an explicit override wins over the session grep).
  private grepArgs(): string[] {
    if (!this.assignGrep) return [];
    // Playwright's grep is --grep / --grep=<x> / -g; any of them in passthrough
    // is an explicit override that must not be doubled up.
    const hasOwnGrep = this.passthroughArgs.some((a) => a === '--grep' || a.startsWith('--grep=') || a === '-g');
    return hasOwnGrep ? [] : ['--grep', this.assignGrep];
  }

  // The only retry trigger for a dropped ack: a reconnect fires onOpen, and any
  // ack that ack() dropped while the socket was down is re-issued on the fresh socket.
  private onOpen(): void {
    if (this.pendingAcks.length === 0) return;
    const acked = this.client?.ack(this.pendingAcks) ?? false;
    if (acked) this.pendingAcks = [];
  }
}
