import { InvalidMachineCountError } from '../errors.js';

export interface MachineCountSources {
  flag?: string;
  env?: string;
}

// resolveMachineCount picks the machine count for an orchestrated mint.
// Precedence: --machines flag > TESTDINO_MACHINES env > throw. The value must be
// a positive integer; anything else (0, negative, non-numeric, blank) is rejected.
export function resolveMachineCount(sources: MachineCountSources = {}): number {
  const raw = sources.flag?.trim() || sources.env?.trim();
  if (!raw) throw new InvalidMachineCountError();

  const n = Number(raw);
  if (!Number.isInteger(n) || n < 1) throw new InvalidMachineCountError(raw);
  return n;
}
