import axios, { type AxiosInstance } from 'axios';
import { sleep } from '../../utils/index.js';
import { DispatchError, classifyDispatchError } from './dispatch-errors.js';
import type { DiscoverSpec } from './types.js';

export interface MintDiscoverRequest {
  suiteFingerprint: string;
  machines: number;
  workers: number;
  fullyParallel: boolean;
  specs: DiscoverSpec[];
  // The discover --grep pattern, persisted so runners re-apply it per batch —
  // otherwise a batch runs whole spec files and executes tests grep excluded.
  grep?: string;
}

export interface MintDiscoverResponse {
  orchestrationId: string;
  machines: number;
  workers: number;
  fullyParallel: boolean;
  specCount: number;
  // false on an idempotent retry of the same (project, suiteFingerprint).
  created: boolean;
}

export interface DiscoverClient {
  mint(req: MintDiscoverRequest): Promise<MintDiscoverResponse>;
}

export interface HttpDiscoverClientOptions {
  token: string;
  serverUrl: string;
  maxAttempts?: number;
  retryDelay?: number;
  timeout?: number;
  onDebug?: (message: string) => void;
}

// Maps a DispatchError from the mint endpoint to an operator-facing sentence.
export function describeMintError(err: DispatchError): string {
  switch (err.httpStatus) {
    case 409:
      return 'already minted for this suite with different machines/workers/fullyParallel';
    case 422:
      return 'no specs, or more than 50000 specs';
    case 404:
      return 'project not found or access denied';
    default:
      return err.message;
  }
}

// HttpDiscoverClient mints an orchestration by POSTing the discovered spec list to
// the data-handler with a td_api_ bearer token. The body is fixed and the mint is
// idempotent on (project, suiteFingerprint), so transient failures retry safely.
export class HttpDiscoverClient implements DiscoverClient {
  private readonly http: AxiosInstance;
  private readonly maxAttempts: number;
  private readonly retryDelay: number;
  private readonly onDebug: (message: string) => void;

  constructor(options: HttpDiscoverClientOptions) {
    this.maxAttempts = options.maxAttempts ?? 3;
    this.retryDelay = options.retryDelay ?? 500;
    this.onDebug = options.onDebug ?? (() => {});
    this.http = axios.create({
      baseURL: options.serverUrl,
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${options.token}` },
      timeout: options.timeout ?? 15_000,
    });
  }

  async mint(req: MintDiscoverRequest): Promise<MintDiscoverResponse> {
    let lastError: DispatchError | null = null;
    for (let attempt = 0; attempt < this.maxAttempts; attempt++) {
      try {
        const res = await this.http.post<MintDiscoverResponse>('/api/v1/orchestrate/discover', req);
        return res.data;
      } catch (error) {
        const classified = classifyDispatchError(error);
        lastError = classified;
        if (!classified.transient) throw classified;
        if (attempt < this.maxAttempts - 1) {
          const delay = this.retryDelay * Math.pow(2, attempt);
          this.onDebug(`mint transient (${classified.kind}/${classified.httpStatus ?? '?'}) — retrying in ${delay}ms`);
          await sleep(delay);
        }
      }
    }
    throw lastError ?? new DispatchError('mint failed', 'network');
  }
}
